// KPI i alarmy liczy KOD (deterministycznie). LLM dostaje gotowe liczby tylko do zredagowania raportu.
const cfg = $('Konfiguracja').first().json;
const b = $input.first().json;
const p = b.public || {};
const o = b.ops || {};
const alarmy = [];
const status = (s) => ({ pending: 'w grze', won: 'trafiony', lost: 'chybiony', void: 'anulowany', none: 'nie powstał' })[s] || s;
const typ = (t) => ({ days3: 'kupon 3-dniowy', days5: 'kupon 5-dniowy' })[t] || t;

const wydatek = o.aiSpendTodayUsd;
if (Number.isFinite(wydatek) && Number.isFinite(o.aiSpendCapUsd) && wydatek >= cfg.spendAlertShare * o.aiSpendCapUsd) {
  alarmy.push(`Wydatki na AI ${wydatek} USD — ${Math.round((100 * wydatek) / o.aiSpendCapUsd)}% dziennego progu (${o.aiSpendCapUsd} USD).`);
}
if (p.dailyPick?.status === 'lost') alarmy.push(`Typ dnia chybiony: ${p.dailyPick.match} (${p.dailyPick.score || '—'}).`);
if (p.coupon?.status === 'lost') {
  const winne = (p.coupon.legs || []).filter((l) => l.status === 'lost').map((l) => `${l.match} ${l.score || ''}`.trim());
  alarmy.push(`Kupon dnia nie wszedł — zawiodło: ${winne.join(', ') || '—'}.`);
}
if (p.coupon?.status === 'none') alarmy.push('Dziś nie powstał kupon dnia (za mało typów zgodnych z rynkiem).');
const a = p.accuracy30 || {};
if (Number.isFinite(a.hitRate) && Number.isFinite(a.usually) && a.settled >= 30 && a.hitRate < a.usually + 10) {
  alarmy.push(`Skuteczność 30 dni ${a.hitRate}% — mniej niż 10 pkt nad normą (${a.usually}%).`);
}
if ((o.newUsers24h ?? 0) === 0) alarmy.push('Brak nowych rejestracji w ostatniej dobie.');
for (const c of o.paidCouponsToday || []) {
  if (c.droppedByNewsCheck > 0) alarmy.push(`${typ(c.type)}: sprawdzanie wiadomości odrzuciło ${c.droppedByNewsCheck} typ(ów).`);
}

const uzycie = (o.usage24h || []).map((u) => `${u.kind}: ${u.calls} wywołań, ${u.users} użytk., ${u.costUsd} USD`).join('; ') || 'brak';
const kpi = [
  `Data: ${b.date}`,
  `Typ dnia: ${p.dailyPick ? `${p.dailyPick.match} — ${p.dailyPick.selection} (${p.dailyPick.probability}%) → ${status(p.dailyPick.status)}${p.dailyPick.score ? ` ${p.dailyPick.score}` : ''}` : 'brak'}`,
  `Dorobek typu dnia: ${p.dailyPickRecord?.won ?? 0}/${p.dailyPickRecord?.total ?? 0}`,
  `Kupon dnia: ${p.coupon ? `${status(p.coupon.status)}${p.coupon.totalOddsText ? `, kurs ${p.coupon.totalOddsText}, szansa ${p.coupon.chance}%` : ''}` : 'brak'}`,
  `Kupony płatne dziś: ${(o.paidCouponsToday || []).map((c) => `${typ(c.type)}: ${status(c.status)} (kurs ${c.totalOdds}, ${c.legs} typów)`).join('; ') || 'brak'}`,
  `Skuteczność 30 dni: ${a.hitRate ?? '—'}% na ${a.settled ?? 0} typach (norma ~${a.usually ?? '—'}%)`,
  `AI dziś: ${wydatek ?? '—'} USD z ${o.aiSpendCapUsd ?? '—'} USD progu; koszt 24h z dziennika: ${(o.usage24h || []).reduce((s, u) => s + u.costUsd, 0).toFixed(3)} USD; użycie: ${uzycie}`,
  `Użytkownicy: +${o.newUsers24h ?? 0} w 24h, razem ${o.usersTotal ?? '—'}`
].join('\n');

const surowy = `🌙 Raport dnia\n\n${kpi}${alarmy.length ? `\n\n⚠️ Alarmy:\n- ${alarmy.join('\n- ')}` : '\n\n✅ Bez alarmów.'}`;

return [{ json: {
  kpi,
  alarmy,
  surowy,
  requestBody: {
    model: cfg.model,
    ...(cfg.reasoningEffort ? { reasoning_effort: cfg.reasoningEffort } : {}),
    max_completion_tokens: 600,
    messages: [
      { role: 'system', content: 'Jesteś analitykiem produktu. Z podanych KPI i alarmów piszesz właścicielowi serwisu krótki raport na Telegram po polsku: 3–5 punktów najważniejszych rzeczy z dnia i jedno konkretne zalecenie na jutro. Liczby przepisujesz dokładnie z danych, nie dodajesz własnych. Gdy są alarmy — zacznij od nich. Najwyżej 700 znaków.' },
      { role: 'user', content: `KPI:\n${kpi}\n\nALARMY:\n${alarmy.length ? alarmy.join('\n') : 'brak'}` }
    ]
  }
} }];

// Gdy LLM zawiedzie — raport i tak idzie, z surowych KPI. Liczby pod spodem zawsze z kodu.
const f = $('KPI i alarmy').first().json;
const tekst = String($input.first().json?.choices?.[0]?.message?.content || '').trim();
const wiadomosc = tekst ? `${tekst}\n\n— — —\n${f.kpi}` : f.surowy;
return [{ json: { wiadomosc: wiadomosc.slice(0, 4000), zrodlo: tekst ? 'llm' : 'surowe KPI', alarmy: f.alarmy.length } }];
